fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let temp: i32 = 20 + sv(t / 32) * 12 / 127;
    host::display::clear(0x0a0e14);
    let colx: i32 = w / 3;
    let colbase: i32 = h - 140;
    let colh: i32 = 200;
    let by: i32 = colbase + 20;
    let mut dy: i32 = 0 - 16;
    while dy <= 16 {
        let mut dx: i32 = 0 - 16;
        while dx <= 16 {
            if dx * dx + dy * dy <= 256 {
                host::display::set_pixel(colx + dx, by + dy, 0xe04040);
            }
            dx = dx + 1;
        }
        dy = dy + 1;
    }
    host::display::fill_rect(colx - 6, colbase - colh, 13, colh, 0x202028);
    let fh: i32 = (temp - 8) * colh / 24;
    host::display::fill_rect(colx - 4, colbase - fh, 9, fh, 0xe04040);
    let mut v: i32 = 10;
    while v <= 30 {
        let ty: i32 = colbase - (v - 8) * colh / 24;
        host::display::draw_line(colx + 10, ty, colx + 18, ty, 0x808080);
        host::display::draw_number(colx + 24, ty - 4, v, 0x808080, 1);
        v = v + 5;
    }
    host::display::draw_number(colx - 70, colbase - colh, temp, 0xffffff, 4);
    host::display::draw_string(colx - 70, colbase - colh + 36, "DEG C", 0x808080, 1);
    let sy: i32 = h - 60;
    let mut x: i32 = 0;
    while x < w {
        let tv: i32 = 20 + sv((t - (w - x) * 4) / 32) * 12 / 127;
        host::display::fill_rect(x, sy + 24 - (tv - 8), 2, 2, 0x40c0ff);
        x = x + 4;
    }
    host::display::draw_string(8, sy - 12, "HISTORY", 0x606060, 1);
    host::display::present();
}
